CREATE DATABASE IF NOT EXISTS network_support CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE network_support;
CREATE TABLE roles(id TINYINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(40) NOT NULL UNIQUE);
INSERT INTO roles(name) VALUES ('Super Administrator'),('Administrator'),('Network Technician'),('CCS Staff');
CREATE TABLE offices(id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL UNIQUE,department VARCHAR(120),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE event_categories(id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL UNIQUE,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO event_categories(name,sort_order) VALUES ('Barangay Mobile Outreach (Go-to-Brgy)',10),('Community Outreach Services',20),('Official Event',30),('Emergency Support',40),('Training',50),('Seminar',60),('Meeting',70),('Conference',80),('Workshop',90),('Other',100);
INSERT INTO offices(name,department) VALUES ('National Office','ICT'),('Regional Office North','Administration'),('Regional Office South','Administration');
CREATE TABLE users(id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,full_name VARCHAR(120) NOT NULL,username VARCHAR(60) NOT NULL UNIQUE,email VARCHAR(150) NOT NULL UNIQUE,phone_number VARCHAR(30) NULL,password_hash VARCHAR(255) NOT NULL,office_id INT UNSIGNED NULL,position_title VARCHAR(120),role_id TINYINT UNSIGNED NOT NULL,status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(office_id) REFERENCES offices(id) ON DELETE SET NULL,FOREIGN KEY(role_id) REFERENCES roles(id));
-- Initial password for default accounts: secret. Change it immediately after installation.
INSERT INTO users(full_name,username,email,password_hash,office_id,position_title,role_id) VALUES ('System Administrator','admin','admin@example.local','$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi.',1,'IT Manager',1),('Amina Technician','amina','amina@example.local','$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi.',1,'Network Technician',3);
CREATE TABLE events(id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,title VARCHAR(200) NOT NULL,description TEXT,office_id INT UNSIGNED NOT NULL,category VARCHAR(60) NOT NULL,location VARCHAR(200) NOT NULL,latitude DECIMAL(9,6) NULL,longitude DECIMAL(9,6) NULL,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,priority ENUM('Low','Normal','High','Urgent') DEFAULT 'Normal',participants INT UNSIGNED DEFAULT 0,bandwidth_mbps INT UNSIGNED DEFAULT 0,primary_connection VARCHAR(100),backup_connection VARCHAR(100),notes TEXT,status ENUM('New','Pending','Assigned','In Progress','Completed','Cancelled','Rescheduled') DEFAULT 'New',travel_order_status ENUM('Not Created','Ongoing','Completed') NOT NULL DEFAULT 'Not Created',travel_order_no VARCHAR(40) NULL,travel_order_created_by INT UNSIGNED NULL,travel_order_created_at DATETIME NULL,travel_order_completed_at DATETIME NULL,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(start_at),INDEX(status),INDEX(travel_order_status),FOREIGN KEY(office_id) REFERENCES offices(id),FOREIGN KEY(created_by) REFERENCES users(id),FOREIGN KEY(travel_order_created_by) REFERENCES users(id));
CREATE TABLE event_assignments(id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,event_id INT UNSIGNED NOT NULL,technician_id INT UNSIGNED NOT NULL,is_team_lead TINYINT(1) NOT NULL DEFAULT 0,assigned_by INT UNSIGNED NOT NULL,assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,status ENUM('New Assignment','Accepted','In Progress','Completed','Cancelled') DEFAULT 'New Assignment',accepted_at DATETIME NULL,started_at DATETIME NULL,completed_at DATETIME NULL,completion_notes TEXT,problems TEXT,actions_taken TEXT,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE,FOREIGN KEY(technician_id) REFERENCES users(id),FOREIGN KEY(assigned_by) REFERENCES users(id),INDEX(technician_id,status));
CREATE TABLE equipment(id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,category VARCHAR(80),serial_number VARCHAR(100),quantity_available INT UNSIGNED DEFAULT 0,quantity_assigned INT UNSIGNED DEFAULT 0,condition_status VARCHAR(50) DEFAULT 'Good',storage_location VARCHAR(120));
INSERT INTO equipment(name,category,quantity_available,condition_status,storage_location) VALUES ('Starlink Kit','Internet',2,'Good','ICT Store'),('Gigabit Router','Network',6,'Good','ICT Store'),('Access Point','Network',12,'Good','ICT Store'),('Ethernet Cable','Cable',50,'Good','ICT Store'),('UPS','Power',4,'Good','ICT Store');
CREATE TABLE event_equipment(event_id INT UNSIGNED,equipment_id INT UNSIGNED,quantity INT UNSIGNED NOT NULL,PRIMARY KEY(event_id,equipment_id),FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE,FOREIGN KEY(equipment_id) REFERENCES equipment(id));
CREATE TABLE notifications(id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id INT UNSIGNED NOT NULL,event_id INT UNSIGNED NULL,message VARCHAR(300) NOT NULL,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE);
CREATE TABLE activity_logs(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id INT UNSIGNED NOT NULL,event_id INT UNSIGNED NULL,action VARCHAR(200) NOT NULL,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE SET NULL);
CREATE TABLE technician_availability(technician_id INT UNSIGNED PRIMARY KEY,availability ENUM('Available','Busy','On Leave','Unavailable') DEFAULT 'Available',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(technician_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE event_reports(id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,assignment_id INT UNSIGNED NOT NULL,performance VARCHAR(100),downtime_minutes INT UNSIGNED DEFAULT 0,recommendations TEXT,FOREIGN KEY(assignment_id) REFERENCES event_assignments(id) ON DELETE CASCADE);
CREATE TABLE event_checklists(id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,assignment_id INT UNSIGNED NOT NULL,item_name VARCHAR(120) NOT NULL,completed BOOLEAN DEFAULT FALSE,FOREIGN KEY(assignment_id) REFERENCES event_assignments(id) ON DELETE CASCADE);
CREATE TABLE event_attachments(id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,event_id INT UNSIGNED NOT NULL,file_name VARCHAR(255) NOT NULL,file_path VARCHAR(255) NOT NULL,uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE);
